    self.remainingTimes = 0 --- 活动剩余时间
    self.products = {}      --- 商品列表
    self.groupCount = 0     --- 分组数量
end

function MidFestivalMallDojo:__delete()
    self.remainingTimes = nil
    self.products = nil
    self.groupCount = nil
end

