---GroupCount 得到商品分组的数量,顺便排序
function MidFestivalMallDojo:GroupCount()
    local count = table.count(self.products)
    table.sort(self.products, function(a, b)
        return a.goodsGroup < b.goodsGroup
    end)
    self.groupCount = self:GroupCountHelper(self.products, 1, count)
    return self.groupCount
end

---GroupBy 将products分组
function MidFestivalMallDojo:GroupBy()
    local hash = {}
    local list = {}
    for i, v in ipairs(self.products) do
        ---@type MidFestivalProductDojo
        local product = v
        if isNull(hash[checkString(product.goodsGroup)]) then
            hash[checkString(product.goodsGroup)] = {}
        end
        table.insert(hash[checkString(product.goodsGroup)], product)
    end

    -- 辅助结构
    local indexes = {}
    local i = 1
    for k, v in pairs(hash) do
        local index = {
            pos = checkNumber(k),
            realPos = i
        }
        table.insert(indexes, index)
        table.insert(list, v)
        i = i + 1
    end

    table.sort(indexes, function(a, b)
        return a.pos < b.pos
    end)

    local retList = {}
    for _, index in ipairs(indexes) do
        table.insert(retList, list[index.realPos])
    end

    for _, group in ipairs(retList) do
        table.sort(group, function(a, b)
            return checkNumber(a.pos) < checkNumber(b.pos)
        end)
    end

    return retList
end

--region private
function MidFestivalMallDojo:GroupCountHelper(products, i, j)
    if i > j then return 0 end
    if products[i].goodsGroup == products[j].goodsGroup then
        return 1
    end
    local vf = products[i].goodsGroup
    while i < j and products[i].goodsGroup == vf do
        i = i + 1
    end
    local vl = products[j].goodsGroup
    while i < j and products[j].goodsGroup == vl do
        j = j - 1
    end
    return self:GroupCountHelper(products, i, j) + 2
end
--endregion private

return MidFestivalMallDojo